<script setup lang="ts">
import { onShow } from '@dcloudio/uni-app';import { ref } from 'vue';import { api } from '../../services/api';
const users=ref<any[]>([]);const showForm=ref(false);const employeeNo=ref('');const name=ref('');const role=ref('NURSE');
async function load(){try{const r:any=await api('/users?pageSize=100');users.value=r.items??[];}catch(e:any){uni.showToast({title:e.message,icon:'none'});}}onShow(load);
async function create(){try{const user:any=await api('/users','POST',{employeeNo:employeeNo.value,name:name.value,role:role.value});const code:any=await api(`/users/${user.id}/activation-codes`,'POST',{purpose:'ACTIVATE_ACCOUNT',reason:'新人员入科'});uni.showModal({title:'账号创建成功',content:`工号：${user.employeeNo}\n一次性激活码：${code.activationCode}\n请安全转交本人。`,showCancel:false});showForm.value=false;employeeNo.value='';name.value='';await load();}catch(e:any){uni.showToast({title:e.message,icon:'none'});}}
async function disable(user:any){const result:any=await new Promise(r=>uni.showModal({title:'停用账号',editable:true,placeholderText:'请输入停用原因',success:r}));if(!result.confirm||!result.content)return;try{await api(`/users/${user.id}`,'PATCH',{status:'DISABLED',reason:result.content});await load();}catch(e:any){uni.showToast({title:e.message,icon:'none'});}}
</script>
<template><view class="page"><button class="primary-btn" @tap="showForm=!showForm">{{showForm?'取消':'新增人员'}}</button><view v-if="showForm" class="card form"><text>工号</text><input v-model="employeeNo"/><text>姓名</text><input v-model="name"/><text>角色</text><picker :range="['NURSE','COORDINATOR']" @change="role=['NURSE','COORDINATOR'][Number($event.detail.value)]"><view class="picker">{{role}}</view></picker><button class="primary-btn" @tap="create">创建并生成激活码</button></view><view v-for="u in users" :key="u.id" class="card row"><view><text class="name">{{u.name}}</text><text class="muted">{{u.employeeNo}} · {{u.role}}</text></view><view class="right"><text :class="u.status==='ACTIVE'?'ok':'muted'">{{u.status}}</text><button v-if="u.status!=='DISABLED'&&u.role!=='HEAD_NURSE'" class="mini" @tap="disable(u)">停用</button></view></view></view></template>
<style scoped>.form{margin-top:22rpx}.form>text{display:block;margin:18rpx 0 8rpx}.form input,.picker{padding:18rpx;border:1px solid #dce7e8;border-radius:12rpx}.form button{margin-top:22rpx}.row{display:flex;justify-content:space-between;align-items:center}.name,.muted{display:block}.name{font-weight:700}.right{text-align:right}.ok{color:#168269}.mini{margin-top:8rpx;padding:4rpx 14rpx;color:#b95b43;font-size:20rpx;line-height:1.8;background:#fff0eb}</style>
